/** Files imported as plain text with `with { loader: 'text' }` (esbuild text loader, tests only). */
declare module '*/manifest.webmanifest' {
  const content: string;
  export default content;
}
declare module '*/styles.css' {
  const content: string;
  export default content;
}
declare module '*/index.html' {
  const content: string;
  export default content;
}
declare module '*/robots.txt' {
  const content: string;
  export default content;
}
